INSERT INTO `question_certification_test` (`id`, `question`, `answer_correct_id`, `certification_test_id`, `created_at`, `updated_at`) VALUES
(1, 'AI nên được sử dụng trong dạy học với vai trò nào?', '1', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(2, 'Giáo viên nên làm gì khi sử dụng AI trong giảng dạy?', '6', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(3, 'Khi sử dụng AI trong học tập, học sinh cần phải:', '9', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(4, 'Một trong những rủi ro khi phụ thuộc quá nhiều vào AI trong học tập là gì?', '13', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(5, 'Vai trò của giáo viên khi sử dụng AI trong lớp học là gì?', '18', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(6, 'AI có thể hỗ trợ giáo viên trong việc nào sau đây?', '24', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(7, 'Trí tuệ nhân tạo (AI) là gì?', '25', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(8, 'AI có thể giúp học sinh cá nhân hóa trải nghiệm học tập bằng cách nào?', '29', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(9, 'AI có thể được sử dụng để:', '34', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(10, 'Lợi ích chính của AI trong việc đánh giá học sinh là gì?', '37', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(11, 'Một trong những ứng dụng của AI trong việc tạo đề kiểm tra là gì?', '41', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(12, 'Chatbot AI có thể được sử dụng trong lớp học để:', '46', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(13, 'Hạn chế của ChatGPT trong dạy học là gì?', '50', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(14, 'Gamma là công cụ gì?', '53', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(15, 'Tính năng nổi bật của Gamma trong dạy học là gì?', '57', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(16, 'Giáo viên có thể sử dụng AI như thế nào để theo dõi tiến độ học tập của học sinh?', '61', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(17, 'AI có thể giúp giáo viên cải thiện phương pháp giảng dạy bằng cách nào?', '65', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(18, 'Lợi ích chính của việc sử dụng AI trong quản lý hệ thống giáo dục là gì?', '69', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(19, 'AI có thể giúp quản lý sự tiến bộ của học sinh thông qua việc nào sau đây?', '73', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(20, 'AI có thể hỗ trợ giáo viên phân tích phản hồi của học sinh bằng cách nào?', '77', 1, '2024-10-02 10:06:59', '2024-10-02 10:06:59'),
(21, 'câu hỏi 1', '81', 2, '2024-10-02 14:56:58', '2024-10-02 14:56:58'),
(22, 'câu hỏi 2', '86', 2, '2024-10-02 14:56:58', '2024-10-02 14:56:58'),
(93, 'Ngành Thiết kế Mỹ thuật số tại Đại học FPT phát triển theo định hướng nào?', '360', 3, '2024-10-08 10:26:24', '2024-10-08 10:26:24'),
(94, '100% sinh viên Đại học FPT được học 1 học kỳ Tiếng Anh tại nước ngoài ở năm học thứ mấy?', '363', 3, '2024-10-08 10:26:24', '2024-10-08 10:26:24'),
(95, 'Tiếng Anh và ngôn ngữ thứ hai nào được đào tạo cho sinh viên ngành Thiết kế Mỹ thuật số?', '368', 3, '2024-10-08 10:26:24', '2024-10-08 10:26:24'),
(96, 'Chương trình học ngành Công nghệ thông tin tại Đại học FPT có bao nhiêu học kỳ chuyên ngành?', '374', 3, '2024-10-08 10:26:24', '2024-10-08 10:26:24'),
